"""Independent SOW check for a Northwind schedule.csv. Usage: check.py export.csv schedule.csv roster.csv"""
import sys, math
from collections import defaultdict
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
import pandas as pd

sys.path.insert(0, "/app")
from wfm.staffing.erlang import required_agents

Z = ZoneInfo("America/Chicago")
SLA = {"priority": (0.9, 30), "standard": (0.8, 20), "vip": (0.9, 20)}
TPL = {"E8": [(6, 14)], "D8": [(9, 17)], "L8": [(13, 21)], "N8": [(16, 24)], "P6a": [(7, 13)], "P6b": [(15, 21)],
       "P4": [(10, 14)], "S44": [(8, 12), (16, 20)]}

exp, schp, rosp = sys.argv[1:4]
df = pd.read_csv(exp)
df["utc"] = pd.to_datetime(df.interval_start_local.str.slice(0, 16) + df.utc_offset, format="%Y-%m-%d %H:%M%z", utc=True).dt.floor("30min")
df = df.groupby(["queue", "utc"]).apply(lambda g: pd.Series({"volume": g.volume.sum(), "aht": (g.volume * g.aht_sec).sum() / g.volume.sum() if g.volume.sum() > 0 else g.aht_sec.mean()}), include_groups=False).reset_index()
mon = df.utc.min().tz_convert(Z).normalize()
start = mon.tz_convert("UTC"); end = (mon + pd.Timedelta(days=7)).tz_localize(None).tz_localize(Z).tz_convert("UTC")
grid = list(pd.date_range(start, end, freq="30min", inclusive="left"))
print("intervals_in_week", len(grid))
req = {}
vol = {}
for r in df.itertuples():
    loc = r.utc.tz_convert(Z); h = loc.hour + loc.minute / 60
    lo, hi = (8, 20) if r.queue == "vip" else (6, 24)
    n = required_agents(r.volume, 1800, r.aht, *SLA[r.queue], occupancy_cap=0.85) if lo <= h < hi else 0
    req[(r.queue, r.utc)] = n
reqh = sum(req.values()) * 0.5
s = pd.read_csv(schp)
for c in ("segment_start_utc", "segment_end_utc", "break_start_utc"):
    s[c] = pd.to_datetime(s[c], utc=True)
ros = pd.read_csv(rosp, dtype=str).set_index("agent_id")
gross = defaultdict(int); brk = defaultdict(int)
for r in s.itertuples():
    for t in grid:
        if r.segment_start_utc <= t < r.segment_end_utc:
            gross[(r.queue, t)] += 1
            if r.break_minutes and r.break_start_utc < t + pd.Timedelta(minutes=30) and t < r.break_start_utc + pd.Timedelta(minutes=int(r.break_minutes)):
                brk[(r.queue, t)] += 1
att = {}
under = 0
for q in SLA:
    lo, hi = (8, 20) if q == "vip" else (6, 24)
    ops = [t for t in grid if lo <= t.tz_convert(Z).hour + t.tz_convert(Z).minute / 60 < hi]
    met = sum(gross[(q, t)] - brk[(q, t)] >= req.get((q, t), 0) for t in ops)
    att[q] = met / len(ops)
    under += sum(max(0, req.get((q, t), 0) - (gross[(q, t)] - brk[(q, t)])) for t in grid) * 0.5
    print(f"sla_attainment_{q} {att[q]:.3f}  ({met}/{len(ops)})")
hours = ((s.segment_end_utc - s.segment_start_utc).dt.total_seconds() / 3600).sum()
print(f"scheduled_hours_total {hours:.1f}\nrequired_hours_total {reqh:.1f}\nratio {hours/reqh:.4f} (<=1.57)")
print(f"understaffed_interval_hours {under:.1f}\nagents_scheduled {s.agent_id.nunique()}")

V = defaultdict(list)
# shifts: group by agent + local date
s["day"] = s.segment_start_utc.dt.tz_convert(Z).dt.date
for (a, d), g in s.groupby(["agent_id", "day"]):
    g = g.sort_values("segment_start_utc")
    tids = set(g.template_id)
    if len(tids) != 1: V["one_template_per_day"].append((a, d))
    tid = g.template_id.iloc[0]
    exp_segs = [(datetime(d.year, d.month, d.day, tzinfo=Z) + timedelta(hours=x), datetime(d.year, d.month, d.day, tzinfo=Z) + timedelta(hours=y)) for x, y in TPL[tid]]
    act = [(r.segment_start_utc.to_pydatetime(), r.segment_end_utc.to_pydatetime()) for r in g.itertuples()]
    if [(x.astimezone(timezone.utc), y.astimezone(timezone.utc)) for x, y in exp_segs] != act: V["template_shape"].append((a, d, tid))
    if len(g.queue.unique()) > 1: V["queue_mix"].append((a, d))
    if len(g) > 1 and ros.loc[a, "contract"] != "PT": V["split_ft"].append((a, d))
    for q in g.queue:
        if q not in ros.loc[a, "skills"].split(";"): V["skill"].append((a, d))
    sh_hours = sum((y - x).total_seconds() for x, y in act) / 3600
    brows = g[g.break_minutes > 0]
    st = act[0][0]
    if sh_hours >= 6:
        if len(brows) != 1 or int(brows.break_minutes.iloc[0]) != 20: V["break_count"].append((a, d)); continue
        b = brows.break_start_utc.iloc[0].to_pydatetime()
        off = (b - st).total_seconds() / 3600
        if not (2 <= off <= 5): V["break_window"].append((a, d, off))
        if b.minute % 30: V["break_aligned"].append((a, d))
        q = g.queue.iloc[0]
        win = [t for t in grid if 2 <= (t.to_pydatetime() - st).total_seconds() / 3600 <= 5 and any(x <= t.to_pydatetime() and t.to_pydatetime() + timedelta(minutes=20) <= y for x, y in act)]
        sur = {t: gross[(q, t)] - req.get((q, t), 0) for t in win}
        bt = pd.Timestamp(b).floor("30min")
        if sur.get(bt, -999) < max(sur.values()): V["break_surplus"].append((a, d, sur.get(bt), max(sur.values())))
    else:
        if len(brows): V["break_on_short"].append((a, d))
# per agent weekly
for a, g in s.groupby("agent_id"):
    h = ((g.segment_end_utc - g.segment_start_utc).dt.total_seconds() / 3600).sum()
    cap = 40 if ros.loc[a, "contract"] == "FT" else 24
    if h > cap + 1e-9: V["weekly_hours"].append((a, h))
    days = sorted(set(g.day)); run = 1
    for d1, d2 in zip(days, days[1:]):
        run = run + 1 if (d2 - d1).days == 1 else 1
        if run > 5: V["consecutive"].append(a); break
    shifts = g.groupby("day").agg(st=("segment_start_utc", "min"), en=("segment_end_utc", "max")).sort_values("st")
    for (s1, e1), (s2, e2) in zip(shifts.values, shifts.values[1:]):
        if (s2 - e1) < pd.Timedelta(hours=11): V["rest"].append((a, s1, s2))
    gg = g.sort_values("segment_start_utc")
    if (gg.segment_start_utc.values[1:] < gg.segment_end_utc.values[:-1]).any(): V["overlap"].append(a)
for t in grid:
    loc = t.tz_convert(Z)
    if 6 <= loc.hour < 24 and gross[("vip", t)] - brk[("vip", t)] < 1: V["vip_cover"].append(t)
print("VIOLATIONS", {k: len(v) for k, v in V.items()} or "none")
for k, v in V.items(): print(k, v[:5])

